mapper.select:
SELECT id, name, is_default AS "isDefault"
FROM bank_account
WHERE id = #{id} AND user_id = #{userId}

SELECT count(*) FROM bank_account
WHERE user_id = #{userId} AND name = #{name}
AND id <> #{id}

mapper.update:
UPDATE bank_account SET is_default = FALSE
WHERE user_id = #{userId} AND is_default
AND id <> #{id}

UPDATE account_transfer
SET transfer_date = #{transferDate}, from_account_id = #{fromAccountId}, to_account_id = #{toAccountId},
    amount = #{amount}, memo = #{memo}
WHERE id = #{id} AND user_id = #{userId}

UPDATE recurring_transfer
SET from_account_id = #{fromAccountId}, to_account_id = #{toAccountId}, amount = #{amount},
    day_of_month = #{dayOfMonth}, adjust = #{adjust}, active = #{active}, memo = #{memo}
WHERE id = #{id} AND user_id = #{userId}

mapper.select:
SELECT r.recurring_transfer_id || '|' || r.period_ym
FROM recurring_transfer_run r
JOIN recurring_transfer i ON i.id = r.recurring_transfer_id
WHERE i.user_id = #{userId}
  AND r.period_ym IN
#{m}
